// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title VaultMultiSig
 * @notice M-of-N multi-signature access control for vault emergency functions.
 *
 * Guardians propose and approve emergency actions (e.g. pause, emergency
 * withdraw). An action is executed only when it has accumulated enough
 * approvals and has not expired.
 *
 * This replaces the single `onlyOwner` emergency controls, requiring
 * consensus from multiple trusted parties before a sensitive operation runs.
 */
contract VaultMultiSig is AccessControl {

    // ── Roles ─────────────────────────────────────────────────────────────────

    bytes32 public constant GUARDIAN_ROLE  = keccak256("GUARDIAN_ROLE");
    bytes32 public constant EMERGENCY_ROLE = keccak256("EMERGENCY_ROLE");

    // ── Config ────────────────────────────────────────────────────────────────

    /// @notice Number of guardian approvals required to execute an action.
    uint256 public requiredGuardians;

    /// @notice Window (seconds) within which an approved action must be executed.
    uint256 public actionWindow = 24 hours;

    // ── Emergency action ─────────────────────────────────────────────────────

    struct EmergencyAction {
        address   target;
        bytes     data;
        uint256   timestamp;
        uint256   approvalCount;
        bool      executed;
        mapping(address => bool) approvals;
    }

    mapping(bytes32 => EmergencyAction) public emergencyActions;

    // ── Events ────────────────────────────────────────────────────────────────

    event EmergencyActionProposed(bytes32 indexed actionId, address indexed proposer, address target);
    event EmergencyActionApproved(bytes32 indexed actionId, address indexed guardian);
    event EmergencyActionRevoked(bytes32 indexed actionId, address indexed guardian);
    event EmergencyActionExecuted(bytes32 indexed actionId);
    event RequiredGuardiansUpdated(uint256 oldValue, uint256 newValue);

    // ── Constructor ───────────────────────────────────────────────────────────

    /**
     * @param guardians         Initial guardian addresses.
     * @param _requiredGuardians Number of approvals required.
     */
    constructor(address[] memory guardians, uint256 _requiredGuardians) {
        require(guardians.length > 0,              "No guardians");
        require(_requiredGuardians >= 1,           "Min 1 required");
        require(_requiredGuardians <= guardians.length, "Required > total");

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);

        for (uint256 i = 0; i < guardians.length; i++) {
            _grantRole(GUARDIAN_ROLE, guardians[i]);
        }

        requiredGuardians = _requiredGuardians;
    }

    // ── Proposal lifecycle ────────────────────────────────────────────────────

    /**
     * @notice Propose a new emergency action.
     * @param target Contract to call.
     * @param data   Encoded function call.
     * @return actionId Hash identifying this action.
     */
    function proposeEmergencyAction(
        address      target,
        bytes calldata data
    )
        external
        onlyRole(GUARDIAN_ROLE)
        returns (bytes32 actionId)
    {
        require(target != address(0), "Invalid target");
        actionId = keccak256(abi.encodePacked(target, data, block.timestamp, msg.sender));

        EmergencyAction storage action = emergencyActions[actionId];
        require(action.timestamp == 0, "Action already exists");

        action.target    = target;
        action.data      = data;
        action.timestamp = block.timestamp;

        emit EmergencyActionProposed(actionId, msg.sender, target);
    }

    /**
     * @notice Approve a pending emergency action.
     */
    function approveEmergencyAction(bytes32 actionId) external onlyRole(GUARDIAN_ROLE) {
        EmergencyAction storage action = emergencyActions[actionId];
        require(action.timestamp != 0,           "Unknown action");
        require(!action.executed,                "Already executed");
        require(!action.approvals[msg.sender],   "Already approved");
        require(block.timestamp <= action.timestamp + actionWindow, "Expired");

        action.approvals[msg.sender] = true;
        action.approvalCount++;

        emit EmergencyActionApproved(actionId, msg.sender);
    }

    /**
     * @notice Revoke a previously given approval.
     */
    function revokeApproval(bytes32 actionId) external onlyRole(GUARDIAN_ROLE) {
        EmergencyAction storage action = emergencyActions[actionId];
        require(!action.executed,              "Already executed");
        require(action.approvals[msg.sender],  "Not approved");

        action.approvals[msg.sender] = false;
        action.approvalCount--;

        emit EmergencyActionRevoked(actionId, msg.sender);
    }

    /**
     * @notice Execute an action that has reached the required approval count.
     */
    function executeEmergencyAction(bytes32 actionId) external onlyRole(GUARDIAN_ROLE) {
        EmergencyAction storage action = emergencyActions[actionId];
        require(action.timestamp != 0,           "Unknown action");
        require(!action.executed,                "Already executed");
        require(action.approvalCount >= requiredGuardians, "Insufficient approvals");
        require(block.timestamp <= action.timestamp + actionWindow, "Expired");

        action.executed = true;

        (bool success, bytes memory returnData) = action.target.call(action.data);
        if (!success) {
            assembly { revert(add(returnData, 32), mload(returnData)) }
        }

        emit EmergencyActionExecuted(actionId);
    }

    // ── View helpers ──────────────────────────────────────────────────────────

    function hasApproved(bytes32 actionId, address guardian) external view returns (bool) {
        return emergencyActions[actionId].approvals[guardian];
    }

    function getApprovalCount(bytes32 actionId) external view returns (uint256) {
        return emergencyActions[actionId].approvalCount;
    }

    // ── Admin ─────────────────────────────────────────────────────────────────

    function setRequiredGuardians(uint256 newRequired) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(newRequired >= 1, "Min 1");
        emit RequiredGuardiansUpdated(requiredGuardians, newRequired);
        requiredGuardians = newRequired;
    }

    function setActionWindow(uint256 newWindow) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(newWindow >= 1 hours,  "Min 1 hour");
        require(newWindow <= 7 days,   "Max 7 days");
        actionWindow = newWindow;
    }
}

contracts/automation/ChainlinkCompounder.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import "../VeMEZOAutoCompounder.sol";

/**
 * @title ChainlinkCompounder
 * @notice Chainlink Automation (Keepers v2) integration for the Auto-Compounder vault.
 *
 * Chainlink nodes call `checkUpkeep()` off-chain; when `upkeepNeeded` is true,
 * they call `performUpkeep()` on-chain via a registered Chainlink upkeep.
 *
 * Deployment steps
 * ────────────────
 * 1. Deploy this contract.
 * 2. Register an upkeep at automation.chain.link pointing to this contract.
 * 3. Fund the upkeep with LINK tokens.
 * 4. Call `vault.updateKeeper(address(this))` to authorise this contract.
 */
contract ChainlinkCompounder {

    // ── State ───────────────────────────────────────────────────────────────

    VeMEZOAutoCompounder public immutable vault;

    /// @notice Minimum interval between compounds.
    uint256 public immutable interval;

    uint256 public lastExecution;

    address public owner;

    // ── Events ──────────────────────────────────────────────────────────────

    event CompoundedViaChainlink(uint256 totalRewards, uint256 fee, uint256 compounded);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    // ── Modifiers ────────────────────────────────────────────────────────────

    modifier onlyOwner() {
        require(msg.sender == owner, "ChainlinkCompounder: not owner");
        _;
    }

    // ── Constructor ──────────────────────────────────────────────────────────

    /**
     * @param _vault    Address of the deployed VeMEZOAutoCompounder vault.
     * @param _interval Minimum seconds between compounds (e.g. 21600 for 6 hours).
     */
    constructor(address _vault, uint256 _interval) {
        require(_vault    != address(0), "Invalid vault");
        require(_interval >= 1 hours,    "Interval too short");
        vault    = VeMEZOAutoCompounder(_vault);
        interval = _interval;
        owner    = msg.sender;
    }

    // ── Chainlink interface ───────────────────────────────────────────────────

    /**
     * @notice Called by Chainlink nodes to determine whether upkeep is needed.
     * @return upkeepNeeded True when it is time to compound and it is profitable.
     * @return performData  Encoded gas price passed to performUpkeep (informational).
     */
    function checkUpkeep(
        bytes calldata /* checkData */
    )
        external
        view
        returns (bool upkeepNeeded, bytes memory performData)
    {
        if (block.timestamp < lastExecution + interval) {
            return (false, bytes(""));
        }
        uint256 gasPrice = tx.gasprice;
        if (!vault.checkUpkeep(gasPrice)) {
            return (false, bytes(""));
        }
        performData  = abi.encode(gasPrice);
        upkeepNeeded = true;
    }

    /**
     * @notice Called by Chainlink nodes when `checkUpkeep` returns true.
     */
    function performUpkeep(bytes calldata /* performData */) external {
        require(block.timestamp >= lastExecution + interval, "Too soon");
        lastExecution = block.timestamp;
        (uint256 rewards, uint256 fee, uint256 compounded) = vault.compoundAll();
        emit CompoundedViaChainlink(rewards, fee, compounded);
    }

    // ── Admin ─────────────────────────────────────────────────────────────────

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Zero address");
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }
}

contracts/automation/GelatoCompounder.so.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import "../VeMEZOAutoCompounder.sol";

/// @dev Minimal Gelato Automate interface (resolver-pattern, no external import needed).
interface IAutomate {
    enum Module { RESOLVER, TIME, PROXY, SINGLE_EXEC }
    struct ModuleData {
        Module[] modules;
        bytes[]  args;
    }
    function createTask(
        address execAddress,
        bytes calldata execDataOrSelector,
        ModuleData calldata moduleData,
        address feeToken
    ) external returns (bytes32 taskId);
    function cancelTask(bytes32 taskId) external;
    function getFeeDetails() external view returns (uint256 fee, address feeToken);
}

/**
 * @title GelatoCompounder
 * @notice Gelato-compatible resolver + executor for decentralized compounding.
 *
 * Replaces the single centralised keeper bot with a decentralised executor
 * network. Gelato nodes call `checker()` off-chain; if it returns canExec=true
 * they call `executeCompound()` on-chain.
 *
 * Deployment steps
 * ────────────────
 * 1. Deploy this contract.
 * 2. Fund it with a small ETH/native balance for Gelato fee payment.
 * 3. Call `createTask()` — Gelato registers the resolver-based task.
 * 4. Call `vault.updateKeeper(address(this))` to authorise this contract.
 */
contract GelatoCompounder {

    // ── State ───────────────────────────────────────────────────────────────

    VeMEZOAutoCompounder public immutable vault;
    IAutomate             public immutable automate;

    /// @notice Gelato task identifier (set after createTask()).
    bytes32 public taskId;

    /// @notice Minimum seconds between compounds (default 6 hours).
    uint256 public minInterval = 6 hours;

    uint256 public lastExecution;

    address public owner;

    // ── Events ──────────────────────────────────────────────────────────────

    event TaskCreated(bytes32 indexed taskId);
    event TaskCancelled(bytes32 indexed taskId);
    event CompoundedViaGelato(uint256 totalRewards, uint256 fee, uint256 compounded);
    event MinIntervalUpdated(uint256 oldInterval, uint256 newInterval);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    // ── Modifiers ────────────────────────────────────────────────────────────

    modifier onlyOwner() {
        require(msg.sender == owner, "GelatoCompounder: not owner");
        _;
    }

    // ── Constructor ──────────────────────────────────────────────────────────

    /**
     * @param _vault    Address of the deployed VeMEZOAutoCompounder vault.
     * @param _automate Address of the Gelato Automate contract on this chain.
     */
    constructor(address _vault, address _automate) {
        require(_vault    != address(0), "Invalid vault");
        require(_automate != address(0), "Invalid automate");
        vault    = VeMEZOAutoCompounder(_vault);
        automate = IAutomate(_automate);
        owner    = msg.sender;
    }

    // ── Gelato resolver ──────────────────────────────────────────────────────

    /**
     * @notice Off-chain resolver called by Gelato nodes to decide whether to run.
     * @return canExec     True when compounding is due and profitable.
     * @return execPayload ABI-encoded call to `executeCompound()`.
     */
    function checker()
        external
        view
        returns (bool canExec, bytes memory execPayload)
    {
        if (block.timestamp < lastExecution + minInterval) {
            return (false, bytes("Too soon"));
        }
        if (!vault.checkUpkeep(tx.gasprice)) {
            return (false, bytes("Not profitable"));
        }
        execPayload = abi.encodeWithSelector(this.executeCompound.selector);
        return (true, execPayload);
    }

    // ── Execution ────────────────────────────────────────────────────────────

    /**
     * @notice Execute compoundAll on the vault. Called by Gelato executor.
     */
    function executeCompound() external {
        lastExecution = block.timestamp;
        (uint256 rewards, uint256 fee, uint256 compounded) = vault.compoundAll();
        emit CompoundedViaGelato(rewards, fee, compounded);
    }

    // ── Task management ──────────────────────────────────────────────────────

    /**
     * @notice Register a resolver-based automation task with Gelato.
     * @return newTaskId The Gelato task ID.
     */
    function createTask() external onlyOwner returns (bytes32 newTaskId) {
        require(taskId == bytes32(0), "Task already exists");

        IAutomate.ModuleData memory moduleData;
        moduleData.modules = new IAutomate.Module[](2);
        moduleData.args    = new bytes[](2);

        moduleData.modules[0] = IAutomate.Module.RESOLVER;
        moduleData.modules[1] = IAutomate.Module.PROXY;

        moduleData.args[0] = abi.encode(address(this), abi.encodeWithSelector(this.checker.selector));
        moduleData.args[1] = bytes("");

        newTaskId = automate.createTask(
            address(this),
            abi.encodeWithSelector(this.executeCompound.selector),
            moduleData,
            address(0)   // native token fee
        );

        taskId = newTaskId;
        emit TaskCreated(newTaskId);
    }

    /**
     * @notice Cancel the active Gelato task.
     */
    function cancelTask() external onlyOwner {
        require(taskId != bytes32(0), "No task exists");
        automate.cancelTask(taskId);
        emit TaskCancelled(taskId);
        taskId = bytes32(0);
    }

    // ── Config ────────────────────────────────────────────────────────────────

    function setMinInterval(uint256 _interval) external onlyOwner {
        require(_interval >= 1 hours,  "Min 1 hour");
        require(_interval <= 7 days,   "Max 7 days");
        emit MinIntervalUpdated(minInterval, _interval);
        minInterval = _interval;
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Zero address");
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }

    receive() external payable {}
}

